type BlogPost={slug:string;title:string;category:string;readTime:string;excerpt:string;image:string;alt:string;sections:{heading:string;body:string}[]}
const blogPosts:BlogPost[]=[
 {slug:'start-with-ai-without-coding',title:'A practical way to start using AI without coding',category:'AI basics',readTime:'4 min read',excerpt:'Start with one task, give the tool useful context, and review the result before you use it.',image:blogAiWithoutCode,alt:'A simple two-step workflow for asking a question and reviewing an AI response.',sections:[{heading:'Begin with a task you already know',body:'Choose a small, familiar task: organise notes, outline a message, or compare a few ideas. A clear task gives you something concrete to review.'},{heading:'Give context and ask for a useful format',body:'Explain who the work is for, what information matters, and what shape the response should take. You can refine the result with follow-up questions.'},{heading:'Review before you rely on it',body:'Check names, facts, tone, and missing context. Keep your judgement in the process, and avoid entering sensitive information into tools without an approved safe process.'}]},
 {slug:'from-prompt-to-agent',title:'What changes when you move from a prompt to an AI agent?',category:'Agentic AI',readTime:'6 min read',excerpt:'An agent can connect a model to tools and data. The useful work is designing, testing, and reviewing those connections.',image:blogAiAgents,alt:'A question flows through an AI system connected to tools and data.',sections:[{heading:'A prompt is an instruction',body:'A prompt tells a model what you want it to do in one interaction. Good context and a clear output format can make that interaction more useful.'},{heading:'An agent can use tools and context',body:'An AI agent can be designed to use tools, retrieve relevant information, and work through a task in steps. That makes the design of its data access and actions important.'},{heading:'Build with boundaries',body:'Start with a real use case. Decide what the agent may access, test edge cases, and review the output. In the SARKTEK computer science programme, learners practise Python agents, tool use, retrieval, and database concepts.'}]},
 {slug:'thoughtful-ai-for-lesson-planning',title:'Using AI as a thoughtful classroom planning assistant',category:'AI in education',readTime:'5 min read',excerpt:'Draft lesson ideas, activities, and assessment materials while keeping student privacy and teacher judgement central.',image:blogAiClassroom,alt:'A lesson planning sheet beside a teacher review symbol.',sections:[{heading:'Use it to create a first draft',body:'AI can help outline a lesson, suggest activities, or draft quiz questions and worksheets. Treat the result as material to review, not a finished decision.'},{heading:'Adapt it to your students',body:'Check that examples, reading level, and activities fit the class and learning goals. Revise the language and assessment to reflect your own teaching context.'},{heading:'Protect student information',body:'Do not enter identifiable student details into tools unless your school has approved a safe process. Keep the teacher responsible for feedback and decisions.'}]}
]
const path=window.location.pathname.replace(/\/$/,'')||'/'
const A=({to,children,className='',...props}:{to:string;children:React.ReactNode;className?:string;[key:string]:any})=>{const onClick=(event:React.MouseEvent<HTMLAnchorElement>)=>{props.onClick?.(event);if(event.defaultPrevented||!to.startsWith('/#'))return;const id=to.slice(2);if(window.location.pathname==='/'){const target=document.getElementById(id);if(target){event.preventDefault();window.history.pushState(null,'',to);target.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}}else{event.preventDefault();sessionStorage.setItem('sarktek-scroll-target',id);window.location.assign('/')}};return <a href={to} className={className} {...props} onClick={onClick}>{children}</a>}
function Logo(){return <A to="/" className="logo" aria-label="SARKTEK home"><img className="logo-image" src={sarktekLogo} alt="SARKTEK"/></A>}
function Header(){const[open,setOpen]=useState(false);return <><a href="#main" className="skip">Skip to content</a><header className="header"><div className="nav-wrap"><Logo/><nav className={open?'nav open':'nav'} aria-label="Main navigation"><A to="/courses" onClick={()=>setOpen(false)}>Courses</A><A to="/bootcamps" onClick={()=>setOpen(false)}>Bootcamps</A><A to="/#learning-model" onClick={()=>setOpen(false)}>How we teach</A><A to="/#journal" onClick={()=>setOpen(false)}>Blogs</A><A to="/contact" onClick={()=>setOpen(false)}>Contact</A><A to="/find-your-course" className="nav-cta" onClick={()=>setOpen(false)}>Find your course <ArrowUpRight size={15}/></A></nav><button className="menu-toggle" aria-label={open?'Close menu':'Open menu'} aria-expanded={open} onClick={()=>setOpen(!open)}>{open?<X/>:<Menu/>}</button></div></header></>}
function Footer(){return <footer className="footer"><div className="footer-top"><div className="footer-brand"><Logo/><p>Practical learning for work that keeps changing.</p><A className="footer-contact-link" to="/contact">Get in touch <ArrowUpRight size={16}/></A></div><div className="footer-links"><div><span className="footer-label">Explore</span><A to="/courses">Courses</A><A to="/bootcamps">Bootcamps</A><A to="/#learning-model">How we teach</A></div><div><span className="footer-label">More</span><A to="/#journal">Blogs</A><A to="/contact">Contact Us</A><A to="/find-your-course">Find your course</A></div><div className="footer-contact"><span className="footer-label">Contact</span><a href="tel:+917396681595"><Phone size={15}/> 73966 81595</a><a href="tel:+917702388845"><Phone size={15}/> 77023 88845</a><a href="mailto:info@sarktek.in"><Mail size={15}/> info@sarktek.in</a><a href="https://www.sarktech.in" target="_blank" rel="noreferrer"><Globe2 size={15}/> www.sarktech.in</a><span className="footer-address"><MapPin size={15}/> Madhapur, Hyderabad</span></div></div></div><div className="footer-bottom"><span>© 2026 SARKTEK</span></div></footer>}
function StickyCourseBar(){
 const[visible,setVisible]=useState(false)
 const currentCourse=path.startsWith('/courses/')?courses.find(course=>course.slug===path.slice('/courses/'.length)):undefined
 const currentBootcamp=path.startsWith('/bootcamps/')?bootcamps.find(item=>item.slug===path.slice('/bootcamps/'.length)):undefined
 useEffect(()=>{
  const main=document.querySelector<HTMLElement>('#main')
  if(!main)return
  const hero=main.querySelector<HTMLElement>('.hero,.page-hero,.boot-page-hero,.detail-hero,.boot-detail-hero,.contact-aside,.finder-intro,.not-found')||main.firstElementChild as HTMLElement|null
  if(!hero){const onScroll=()=>setVisible(window.scrollY>240);window.addEventListener('scroll',onScroll,{passive:true});onScroll();return()=>window.removeEventListener('scroll',onScroll)}
  const observer=new IntersectionObserver(([entry])=>setVisible(entry.boundingClientRect.bottom<=0),{threshold:0})
  observer.observe(hero)
  return()=>observer.disconnect()
 },[])
 const home=path==='/';
 const courseCatalog=path==='/courses';
 const bootcampCatalog=path==='/bootcamps';
 const detail=!!(currentCourse||currentBootcamp);
 const branded=home||courseCatalog||bootcampCatalog||detail;
 const applicationHref=currentCourse?`/contact?course=${currentCourse.slug}`:currentBootcamp?`/contact?bootcamp=${currentBootcamp.slug}`:'/find-your-course';
 const secondary=currentCourse||courseCatalog?{href:'/bootcamps',label:'View Bootcamps'}:currentBootcamp?{href:'/courses',label:'Explore Courses'}:home||bootcampCatalog?{href:'/courses',label:'Explore Courses'}:undefined
 return <>
  <aside className={'sticky-course-bar'+(branded?' branded-sticky':'')+(visible?' is-visible':'')} aria-label={home?'Course and academy links':detail?'Programme actions':'Course finder'} aria-hidden={!visible}>
   <A className="btn btn-primary sticky-course-button" to={applicationHref} tabIndex={visible?0:-1}>{detail?'Apply now':'Find your course'} <ArrowUpRight size={17}/></A>
   {branded&&<div className="sticky-association-inline"><span>IN ASSOCIATION WITH</span><img src={donBoscoEmblem} alt="Don Bosco AI Academy"/></div>}
   {secondary&&<A className="btn btn-secondary sticky-course-secondary" to={secondary.href} tabIndex={visible?0:-1}>{secondary.label} <ArrowRight size={16}/></A>}
  </aside>
  {!branded&&<aside className={'sticky-association'+(visible?' is-visible':'')} aria-label="In association with Don Bosco AI Academy" aria-hidden={!visible}><span>IN ASSOCIATION WITH</span><img src={donBoscoEmblem} alt="Don Bosco AI Academy"/></aside>}
 </>
}
function PageFrame({children}:{children:React.ReactNode}){useEffect(()=>{const main=document.querySelector<HTMLElement>('#main');const root=main?.parentElement;if(!main||!root||!('IntersectionObserver'in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const groups='.course-card,.blog-card,.path-card,.boot-card,.boot-artwork,.phase-card,.method-step,.boot-step-grid article,.why-grid article,.detail-facts>div,.boot-facts>div,.outcome-list>div,.contact-form,.finder-box,.privacy-callout,.final-prompt,.catalog-nudge,.sap-slim,.blog-mark,.detail-stamp,.boot-detail-art,.outcome-ticket,.footer-top,.footer-bottom,.hero-art,.hero-actions,.proof-strip>div,.detail-actions,.final-cta>div,.boot-note,.boot-detail-hero,.boot-task-section,.boot-outcome-panel,.course-card-logo';const candidates=Array.from(root.querySelectorAll<HTMLElement>(`h1,h2,p,${groups}`));const targets=candidates.filter(el=>el.matches(groups)||!el.closest(groups));root.classList.add('reveal-enabled');targets.forEach((el,index)=>{el.dataset.reveal='';const siblings=el.parentElement?Array.from(el.parentElement.children).filter(node=>(node as HTMLElement).dataset.reveal!==undefined):[];el.style.setProperty('--reveal-delay',`${Math.min(siblings.length,6)*58}ms`)});const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){(entry.target as HTMLElement).dataset.revealed='true';observer.unobserve(entry.target)}}),{threshold:.12,rootMargin:'0px 0px -5% 0px'});targets.forEach(el=>observer.observe(el));const revealFocused=(event:FocusEvent)=>{const el=(event.target as HTMLElement).closest<HTMLElement>('[data-reveal]');if(el)el.dataset.revealed='true'};main.addEventListener('focusin',revealFocused);return()=>{observer.disconnect();main.removeEventListener('focusin',revealFocused);root.classList.remove('reveal-enabled');targets.forEach(el=>{delete el.dataset.reveal;delete el.dataset.revealed;el.style.removeProperty('--reveal-delay')})}},[]);useEffect(()=>{const id=sessionStorage.getItem('sarktek-scroll-target');if(!id)return;sessionStorage.removeItem('sarktek-scroll-target');requestAnimationFrame(()=>{const target=document.getElementById(id);if(target)target.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})})},[]);return <><Header/><main id="main">{children}</main><Footer/><StickyCourseBar/></>}
function Eyebrow({children}:{children:React.ReactNode}){return <span className="eyebrow"><i/> {children}</span>}
function SectionTitle({title,copy,light=false}:{index?:string;kicker?:string;title:React.ReactNode;copy?:string;light?:boolean}){return <div className={'section-title '+(light?'light':'')}><h2>{title}</h2>{copy&&<p>{copy}</p>}</div>}
function ArrowLink({to,children}:{to:string;children:React.ReactNode}){return <A className="arrow-link" to={to}>{children}<span><ArrowUpRight size={16}/></span></A>}
function ToolMarquee(){const[touching,setTouching]=useState(false);const tools=[{name:'ChatGPT',logo:toolOpenAI},{name:'Gemini',logo:toolGemini},{name:'Claude',logo:toolClaude},{name:'Grok',logo:toolGrok},{name:'GitHub',logo:toolGitHub},{name:'Higgsfield',logo:toolHiggsfield},{name:'Python',logo:toolPython}];const logos=(copy=false)=><div className="tool-wordmark-list" aria-hidden={copy||undefined}>{tools.map(({name,logo})=><span className="tool-wordmark" key={name}><img src={logo} alt={copy?'':name} title={copy?'':name}/></span>)}</div>;return <section className="tools-section" aria-label="Tools used across learning paths"><div className="tools-heading"><div><h2>Tools in practice</h2><p>Tools used or explored across learning paths. Availability varies by programme.</p></div></div><div className="tools-marquee-row"><div className="tools-marquee" tabIndex={0} aria-label="Scrolling tool logos. Focus, hover, or touch to pause." onTouchStart={()=>setTouching(true)} onTouchEnd={()=>setTouching(false)} onTouchCancel={()=>setTouching(false)}><div className={touching?'tools-track is-paused':'tools-track'}>{logos()}{logos(true)}</div></div></div></section>}
function BlogCard({post}:{post:BlogPost}){return <article className="blog-card"><A to="/#journal" className="blog-card-image"><img src={post.image} alt={post.alt} loading="lazy"/></A><div className="blog-card-copy"><span className="blog-meta"><span>{post.category.toUpperCase()}</span><span className="blog-reading-time">{post.readTime}</span></span><h3><A to="/#journal">{post.title}</A></h3><p>{post.excerpt}</p><ArrowLink to="/#journal">Read article</ArrowLink></div></article>}
function CourseDetailVisual({course}:{course:Course}){const isPoster=course.slug==='ai-for-non-ai-people'||course.slug==='agentic-ai-computer-science';const visuals:Record<string,{src:string;alt:string}>={'ai-for-non-ai-people':{src:coursePosterOne,alt:'AI for Non-AI People course poster with programme details.'},'agentic-ai-computer-science':{src:coursePosterTwo,alt:'Agentic AI for Computer Science Students course poster with programme details.'},'ai-for-management':{src:heroLearningPhoto,alt:'A learner uses digital tools to plan and develop practical work.'},'sap-analytics':{src:sapDataPhoto,alt:'A data analyst reviews business analytics dashboards in a modern office.'},'sap-bdc':{src:sapDataPhoto,alt:'A professional reviews connected business data and cloud analytics in an office.'},'sap-cpi':{src:sapDataPhoto,alt:'A technology professional reviews enterprise system integration dashboards.'}};const visual=visuals[course.slug];return <div className={'course-detail-visual'+(isPoster?' is-poster':'')}><img src={visual.src} alt={visual.alt}/>{!isPoster&&<div className="course-visual-caption"><span>{course.category} / FIELD GUIDE</span><b>{course.title}</b><small>Practical learning, grounded in work.</small></div>}</div>}
function CourseCard({course}:{course:Course;index?:number}){const visual=course.slug==='ai-for-non-ai-people'?courseLogoOne:course.slug==='agentic-ai-computer-science'?courseLogoTwo:course.slug==='ai-for-management'?courseLogoThree:undefined;const PlaceholderIcon=course.slug==='ai-for-management'?ChartNoAxesCombined:course.slug==='sap-analytics'?ChartNoAxesCombined:course.slug==='sap-bdc'?Database:Workflow;return <article className="course-card"><div className="card-top"><span className={'tag '+(course.category==='AI'?'tag-ai':'tag-sap')}>{course.category}</span>{course.duration&&<span className="duration-badge"><Clock3 size={14}/><b>{course.duration}</b></span>}</div>{visual?<div className="course-card-logo"><img src={visual} alt={course.title+' programme logo'} loading="lazy"/></div>:<div className={'course-card-logo course-logo-placeholder '+(course.category==='SAP'?'is-sap':'is-ai')} aria-label={`${course.title} logo placeholder`}><span className="course-logo-symbol"><PlaceholderIcon size={25} strokeWidth={1.8}/></span><span><b>{course.category==='SAP'?'SAP':'AI'} / {course.icon}</b><small>{course.category==='SAP'?'DATA · SYSTEMS · INTEGRATION':'PRACTICAL AI PROGRAMME'}</small></span></div>}<h3>{course.title}</h3><p>{course.summary}</p><div className="card-meta"><span className="meta-audience">{course.audience}</span></div><ArrowLink to={`/courses/${course.slug}`}>View course</ArrowLink></article>}
const bootcampImages:Record<string,string>={'priests-religious-leaders':bootPriests,'school-teachers':bootTeachers,'ngos-social-workers':bootNgos,'small-mid-size-business-owners':bootBusinessOwners,'ai-for-change-makers':bootChangeMakers,'ai-for-youth':bootYouth}
function BootcampArtwork({item}:{item:Bootcamp}){return <span className="boot-icon-art"><img src={bootcampImages[item.slug]} alt={item.title+' original artwork'} loading="lazy"/></span>}
function BootcampDetailArtwork({item}:{item:Bootcamp}){return <div className="boot-detail-image"><img src={bootcampImages[item.slug]} alt={item.title+' workshop'} loading="lazy"/></div>}
function BootcampCard({item,index=0,showFacts=true}:{item:Bootcamp;index?:number;showFacts?:boolean}){return <article id={'audience-'+item.slug} className={'boot-card boot-'+index}><div className="boot-card-head"><span className="eyebrow">{item.short}</span><BootcampArtwork item={item}/></div><div className="boot-copy"><h3>{item.title}</h3><p>{item.headline}</p>{showFacts&&<div className="fact-chips"><span>10 hours</span><span>In person</span></div>}<ArrowLink to={`/bootcamps/${item.slug}`}>View details</ArrowLink></div></article>}
function HeroArt(){return <div className="hero-art learning-art" aria-hidden="true"><div className="learning-board"><div className="board-top"><span>PROJECT / AI IN PRACTICE</span><span className="board-status">FIELD STUDY</span></div><div className="board-intro"><span>WORKING AI AGENT</span><h3>From a real question<br/>to a useful tool.</h3><p>Plan it. Build it. Review what it gets right.</p></div><div className="board-flow"><div><span>01</span><b>Choose a task</b><small>Start with a real need</small></div><i/><div><span>02</span><b>Build a response</b><small>Use tools and context</small></div><i/><div><span>03</span><b>Review the result</b><small>Keep human judgement</small></div></div><div className="board-bottom"><span>PROJECT NOTE / 001</span><b><Check size={13}/> READY TO SHARE</b></div></div><div className="board-sticky">LEARN <i/> APPLY <i/> BUILD</div></div>}
function HeroCourseCarousel(){
 const slides=[
  {href:'/courses/ai-for-non-ai-people',title:'AI for Non-AI People',src:coursePosterOne,alt:'AI for Non-AI People course poster'},
  {href:'/courses/agentic-ai-computer-science',title:'Agentic AI for Computer Science Students',src:coursePosterTwo,alt:'Agentic AI for Computer Science Students course poster'}
 ]
 const[index,setIndex]=useState(0)
 const[touchStart,setTouchStart]=useState<number|null>(null)
 const go=(direction:number)=>setIndex(current=>(current+direction+slides.length)%slides.length)
 const slide=slides[index]
 return <div className="hero-art hero-course-carousel" role="region" aria-roledescription="carousel" aria-label="Featured AI courses" onKeyDown={event=>{if(event.key==='ArrowLeft')go(-1);if(event.key==='ArrowRight')go(1)}} onTouchStart={event=>setTouchStart(event.touches[0].clientX)} onTouchEnd={event=>{if(touchStart===null)return;const delta=event.changedTouches[0].clientX-touchStart;if(Math.abs(delta)>45)go(delta<0?1:-1);setTouchStart(null)}}>
  <A key={slide.title} className="hero-course-slide" to={slide.href} aria-label={'Explore '+slide.title}><img src={slide.src} alt={slide.alt} fetchPriority="high"/></A>
  <button className="hero-carousel-control is-previous" type="button" aria-label="Previous featured course" onClick={()=>go(-1)}><ChevronLeft size={20}/></button>
  <button className="hero-carousel-control is-next" type="button" aria-label="Next featured course" onClick={()=>go(1)}><ChevronRight size={20}/></button>
  <div className="hero-carousel-dots" aria-label="Choose featured course">{slides.map((item,i)=><button key={item.title} type="button" aria-label={'Show '+item.title} aria-current={i===index?'true':undefined} onClick={()=>setIndex(i)}/>)}</div>
 </div>
}
function Home(){return <PageFrame><section className="hero"><div className="hero-grid"><div className="hero-copy"><Eyebrow>LEARNING FOR WHAT’S NEXT</Eyebrow><h1><span className="hero-title-line">Learn the technology</span><span className="hero-title-line hero-title-last">that <em>empowers</em><span className="period">.</span></span></h1><p>Practical, project-based training in AI and SAP, for students and working professionals.</p><div className="hero-actions"><A className="btn btn-primary" to="/courses">Explore courses <ArrowUpRight size={17}/></A><A className="btn btn-secondary hero-secondary" to="/bootcamps">View bootcamps <ArrowRight size={16}/></A></div></div><HeroCourseCarousel/></div></section>
 <ToolMarquee/>


 <section className="method section-pad" id="learning-model"><div className="method-intro"><Eyebrow>THE SARKTEK LEARNING MODEL</Eyebrow><h2>From understanding<br/>to <em>Applied Knowledge.</em></h2><p style={{color:'#FFFFFF',WebkitTextFillColor:'#FFFFFF'}}>Three AI programmes use this four-phase learning structure.</p><A className="btn btn-secondary" to="/#learning-model">Why learn with us <ArrowRight size={16}/></A></div><div className="method-steps">{[{title:'Learn',Icon:BookOpen},{title:'Apply',Icon:FlaskConical},{title:'Build',Icon:Hammer},{title:'Launch',Icon:Rocket}].map(({title,Icon},i)=><div className={'method-step step-'+i} key={title}><span>0{i+1}</span><div className="step-mark"><Icon size={25} strokeWidth={1.6} color="#FFFFFF"/></div><h3>{title}</h3><p>{['Learn the core ideas and tools.','Apply them to practical scenarios.','Build a project you can explain.','Present your work and plan next steps.'][i]}</p>{i<3&&<ArrowRight className="step-arrow" size={17} color="#FFFFFF"/>}</div>)}</div><span className="method-note">Applied to the three AI courses where this structure is specified.</span></section>
 <section className="featured section-pad" id="courses"><div className="featured-head"><SectionTitle index="02" kicker="LEARN BY MAKING" title={<>Explore AI and SAP<br/><em>courses.</em></>} copy="Six programmes for different backgrounds and goals."/><A className="btn btn-secondary" to="/courses">See all courses <ArrowRight size={16}/></A></div><div className="course-grid home-course-grid">{courses.map(c=><CourseCard key={c.slug} course={c}/>)}</div></section>
 <section className="bootcamp-section section-pad" id="bootcamps"><SectionTitle index="03" kicker="SHORT, FOCUSED, IN PERSON" title={<>Our <em>Bootcamps</em></>} copy="A couple of practical workshops to get you started. Browse all five programmes on the Bootcamps page."/><div className="bootcamp-grid">{bootcamps.slice(0,2).map((b,i)=><BootcampCard key={b.slug} item={b} index={i}/>)}</div><div className="center-link"><A className="btn btn-secondary bootcamp-cta" to="/bootcamps">View all bootcamps <ArrowUpRight size={16}/></A></div></section>
 <section className="home-blog section-pad" id="journal"><div className="blog-section-head"><div><Eyebrow>FROM THE BLOGS</Eyebrow><h2>Ideas to take<br/><em>into your work.</em></h2><p>Practical notes on AI, SAP, and learning by doing.</p></div><A className="btn btn-secondary" to="/#journal">View all articles <ArrowUpRight size={16}/></A></div><div className="blog-grid">{blogPosts.map(post=><BlogCard key={post.slug} post={post}/>)}</div></section>
 <section className="finder-teaser"><div><Eyebrow>NOT SURE WHERE TO BEGIN?</Eyebrow><h2>Let’s find your <em>fit.</em></h2><p>Answer three questions to find a course or bootcamp to explore.</p></div><A to="/find-your-course" className="btn btn-secondary">Start the course finder <ArrowUpRight size={16}/></A></section>
 <section className="final-cta"><div className="final-cta-inner"><div className="final-cta-copy"><span className="eyebrow">YOUR NEXT STEP</span><h2>Start with a skill.<br/><em>Leave with something real.</em></h2><p>Explore AI and SAP courses built around practical work.</p><div className="final-cta-actions"><A className="btn btn-primary" to="/courses">Explore courses <ArrowUpRight size={16}/></A><A className="btn btn-secondary" to="/contact">Ask a question <ArrowRight size={16}/></A></div></div><div className="final-cta-art"><img src={ctaLearningPhoto} alt="Learner and mentor planning a practical project together." loading="lazy"/></div></div></section></PageFrame>}
function PageHero({label,title,copy,crumb,action}:{label:string;title:React.ReactNode;copy:string;crumb?:string;action?:React.ReactNode}){return <section className="page-hero"><div className="crumb"><A to="/">Home</A><ChevronRight size={13}/><span>{crumb||label}</span></div><div className="page-hero-content"><div><Eyebrow>{label}</Eyebrow><h1>{title}</h1><p>{copy}</p></div>{action?<div className="page-hero-action">{action}</div>:<span className="page-stamp">SARKTEK<br/>LEARNING<br/>JOURNAL <ArrowDownRight size={20}/></span>}</div></section>}
function CoursesPage(){const params=new URLSearchParams(window.location.search);const[filter,setFilter]=useState(params.get('category')||'All');const visible=useMemo(()=>courses.filter(c=>filter==='All'||c.category===filter),[filter]);return <PageFrame><PageHero label="COURSE CATALOGUE / 06 PROGRAMMES" title={<>Find your next<br/><em>practical skill.</em></>} copy="Browse AI and SAP courses by what you want to work on." action={<A className="btn btn-primary" to="/find-your-course">Find your course <ArrowUpRight size={16}/></A>}/><section className="catalog section-pad"><div className="catalog-toolbar"><div className="filters" role="group" aria-label="Filter courses by category">{['All','AI','SAP'].map(f=><button className={filter===f?'filter active':'filter'} onClick={()=>setFilter(f)} aria-pressed={filter===f}>{f==='All'?'All courses':f+' courses'}</button>)}</div><span aria-live="polite">{visible.length} {visible.length===1?'course':'courses'}</span></div><div className="course-grid">{visible.map((c,i)=><CourseCard key={c.slug} course={c} index={courses.indexOf(c)}/>)}</div>{visible.length===0&&<div className="empty">No courses match these filters. <button onClick={()=>setFilter('All')}>Clear filters</button></div>}</section><section className="catalog-nudge"><span className="eyebrow">EXPLORE BOOTCAMPS</span><h2>Looking for a focused introduction?</h2><p>Our in-person AI bootcamps are separate from these multi-session programmes.</p><ArrowLink to="/bootcamps">View all bootcamps</ArrowLink></section></PageFrame>}
function CourseDetail({course}:{course:Course}){return <PageFrame><div className="crumb detail-crumb"><A to="/">Home</A><ChevronRight size={13}/><A to="/#courses">Courses</A><ChevronRight size={13}/><span>{course.title}</span></div><section className="detail-hero"><div className="detail-copy"><Eyebrow>{course.category} COURSE / {course.duration||'PROGRAMME DETAILS'}</Eyebrow><h1>{course.title}</h1><p>{course.summary}</p><div className="detail-actions"><A className="btn btn-primary" to={`/contact?course=${course.slug}`}>Apply now <ArrowUpRight size={16}/></A><a className="btn btn-secondary" href="#curriculum">Explore the curriculum <ArrowDownRight size={16}/></a></div></div><CourseDetailVisual course={course}/></section><section className="detail-facts">{course.duration&&<div className="fact-duration"><span>DURATION</span><b><Clock3 size={14}/>{course.duration}</b></div>}{course.sessions&&<div><span>STRUCTURE</span><b>{course.sessions}</b></div>}{course.delivery&&<div><span>DELIVERY</span><b>{course.delivery}</b></div>}<div><span>FOR</span><b>{course.audience}</b></div><div><span>CODING</span><b>{course.slug==='ai-for-management'||course.slug==='ai-for-non-ai-people'?'Not required':course.slug==='agentic-ai-computer-science'?'Basic programming':'See prerequisites'}</b></div></section><section className="detail-section section-pad"><div><Eyebrow>WHAT YOU’LL BE ABLE TO DO</Eyebrow><h2>Build skills you<br/><em>can put to work.</em></h2></div><div className="outcome-list">{course.outcomes.map((o,i)=><div><span>0{i+1}</span><b>{o}</b><Check size={16}/></div>)}</div></section>{course.phases?<section className="curriculum section-pad" id="curriculum"><div className="curriculum-head"><div><Eyebrow>THE LEARNING JOURNEY</Eyebrow><h2>Four phases.<br/><em>One growing body of work.</em></h2></div></div><div className="phase-grid">{course.phases.map((phase,i)=><article className="phase-card"><span>PHASE 0{i+1}</span><h3>{phase.name}</h3><p>{phase.description}</p><ul>{phase.points.map(p=><li>{p}</li>)}</ul></article>)}</div></section>:<section className="curriculum section-pad" id="curriculum"><div className="curriculum-head"><div><Eyebrow>WHAT YOU’LL LEARN</Eyebrow><h2>From enterprise data<br/><em>to useful outcomes.</em></h2></div><p>{course.summary}</p></div><div className="outcome-list curriculum-list">{(course.curriculum||course.outcomes).map((o,i)=><div><span>0{i+1}</span><b>{o}</b><ArrowUpRight size={15}/></div>)}</div></section>}<section className="audience-prereq section-pad"><div><Eyebrow>WHO IT’S FOR</Eyebrow><h2>Bring your<br/><em>point of view.</em></h2><p>{course.audience}</p></div><div><Eyebrow>BEFORE YOU BEGIN</Eyebrow><h2>A useful<br/><em>starting point.</em></h2><ul>{course.prerequisites.map(p=><li><Check size={15}/>{p}</li>)}</ul></div></section><section className="related section-pad"><div className="featured-head"><SectionTitle index="NEXT" kicker="KEEP EXPLORING" title={<>Related <em>courses.</em></>} copy="There’s more than one way to build practical confidence."/></div><div className="course-grid">{courses.filter(c=>c.slug!==course.slug).slice(0,3).map(c=><CourseCard course={c} index={courses.indexOf(c)}/>)}</div></section><FinalPrompt/></PageFrame>}
function BootcampsPage(){return <PageFrame><section className="boot-page-hero"><div className="crumb"><A to="/">Home</A><ChevronRight size={13}/><span>Bootcamps</span></div><div className="boot-page-hero-grid"><div className="boot-page-copy"><Eyebrow>FIVE BOOTCAMPS / PRACTICAL AI</Eyebrow><h1>AI for the work<br/><em>you already do.</em></h1><p>Learn practical AI through tasks from your work. Choose the audience that fits you, practise together in person, and complete three real tasks.</p><div className="boot-hero-actions"><A className="btn btn-primary" to="#audiences">Choose your audience <ArrowDownRight size={16}/></A><A className="btn btn-secondary" to="/courses">Explore longer courses <ArrowUpRight size={16}/></A></div></div><div className="boot-story-board boot-hero-photo"><img src={heroLearningPhoto} alt="A learner practising with digital tools in a workshop setting."/></div></div><div className="boot-facts boot-hero-facts"><div><Clock3/><span><b>10 hours</b><small>One focused format</small></span></div><div><UsersRound/><span><b>In person</b><small>Learn together</small></span></div><div><Check/><span><b>Three real tasks</b><small>Completed by every learner</small></span></div></div></section><section className="boot-index section-pad" id="audiences"><div className="boot-index-head"><Eyebrow>CHOOSE YOUR CONTEXT</Eyebrow><h2>Start with your work.<br/><em>Make AI practical.</em></h2><p>Each workshop starts with AI fundamentals, then focuses on tasks and safeguards for a specific audience.</p></div><nav className="audience-jump" aria-label="Choose your bootcamp audience">{bootcamps.map((b,i)=><a key={b.slug} href={'#audience-'+b.slug}>{b.short}<ArrowDownRight size={14}/></a>)}</nav><div className="bootcamp-grid">{bootcamps.map((b,i)=><BootcampCard key={b.slug} item={b} index={i} showFacts={false}/>)}</div></section><section className="boot-format-note"><div><Eyebrow>A DISTINCT FORMAT</Eyebrow><h2>Short workshop.<br/><em>Longer learning paths.</em></h2><p>Bootcamps are separate from the multi-session AI and SAP courses.</p></div><A className="btn btn-secondary" to="/courses">Compare all courses <ArrowUpRight size={16}/></A></section><FinalPrompt label="PICK THE WORKSHOP THAT FITS" title="Explore a bootcamp for your role." action="Ask about a bootcamp"/></PageFrame>}
function BootcampDetail({item}:{item:Bootcamp}){return <PageFrame><div className="crumb detail-crumb"><A to="/">Home</A><ChevronRight size={13}/><A to="/bootcamps">Bootcamps</A><ChevronRight size={13}/><span>{item.short}</span></div><section className="boot-detail-hero"><div className="boot-detail-copy"><Eyebrow>10 HOURS / IN PERSON / {item.audience.toUpperCase()}</Eyebrow><h1>{item.headline}</h1><p>{item.kicker}. Build practical skills around familiar work, with responsible use and human review at every step.</p><div className="detail-actions"><A className="btn btn-primary" to="/contact">Ask about this bootcamp <ArrowUpRight size={16}/></A><a className="btn btn-secondary" href="#boot-steps">Explore the workshop <ArrowDownRight size={16}/></a></div><div className="boot-detail-factline"><span><Clock3 size={17}/>10 hours</span><span><UsersRound size={17}/>In person</span><span><Check size={17}/>Three real tasks</span></div></div><BootcampDetailArtwork item={item}/></section><section className="boot-steps section-pad" id="boot-steps"><div className="curriculum-head"><div><Eyebrow>YOUR WORKSHOP, STEP BY STEP</Eyebrow><h2>Learn the tools.<br/><em>Apply them to your world.</em></h2></div><p>Each 10-hour workshop moves from AI fundamentals into role-specific practice. Every learner completes three real tasks.</p></div><div className="boot-step-grid boot-step-grid-five">{item.curriculum.map((phase,i)=><article key={phase.title}><span>0{i+1} / {phase.title.toUpperCase()}</span><h3>{phase.title}</h3><p>{phase.description}</p></article>)}</div></section><section className="boot-task-section"><div><Eyebrow>THREE PRACTICAL OUTPUTS</Eyebrow><h2>Work you can<br/><em>take with you.</em></h2><p>Bring real examples from your role. Practise with guided support, then review every result before using it.</p><A className="btn btn-secondary" to="/contact">Ask about the workshop <ArrowUpRight size={16}/></A></div><div className="boot-task-list">{item.tasks.map((task,i)=><div key={task}><span>0{i+1}</span><b>{task}</b><ArrowUpRight size={16}/></div>)}</div></section><section className="privacy-callout"><span><ShieldCheck size={20}/></span><div><Eyebrow>RESPONSIBLE USE</Eyebrow><h3>Keep human judgement in the loop.</h3><p>{item.privacy}</p></div></section><section className="boot-outcome-panel"><div><Eyebrow>THE OUTCOME</Eyebrow><h2>{item.result||item.outcome}</h2><p>{item.outcome}</p></div><div className="outcome-ticket"><span>10 HOURS / IN PERSON</span><b>{item.result||item.outcome}</b><span>AI FOR {item.short.toUpperCase()}</span></div></section><FinalPrompt label="CURIOUS ABOUT THIS BOOTCAMP?" title="Let’s talk about what fits." action="Ask about this bootcamp"/></PageFrame>}
function FinalPrompt({label='READY WHEN YOU ARE',title='Find the next step that fits.',action='Explore your options'}:{label?:string;title?:string;action?:string}){return <section className="final-prompt"><div><Eyebrow>{label}</Eyebrow><h2>{title}</h2></div><A className="btn btn-primary" to="/contact">{action} <ArrowUpRight size={16}/></A></section>}
function WhyPage(){const principles=[{n:'01',t:'Hands-on by design',d:'Labs, case studies and mini-projects move ideas into practice.',Icon:FlaskConical},{n:'02',t:'Connected to industry',d:'Course content reflects tools and scenarios used in enterprise work.',Icon:Building2},{n:'03',t:'A path that fits you',d:'Tracks support different starts, from non-technical learners to SAP professionals.',Icon:Route},{n:'04',t:'Support along the way',d:'Mentor guidance helps you work through challenging ideas.',Icon:LifeBuoy}];return <PageFrame><PageHero label="WHY SARKTEK" title={<>Useful skills.<br/><em>Real practice.</em></>} copy="We make complex ideas easier to put to work through clear learning paths, guided practice and projects grounded in real situations."/><section className="why-intro section-pad"><div><Eyebrow>OUR POINT OF VIEW</Eyebrow><h2>Good learning should<br/>leave you with <em>proof.</em></h2></div><p>SARKTEK connects AI and SAP learning to human and business problems, then gives learners room to practise and share what they’ve made.</p></section><section className="why-grid section-pad">{principles.map(({n,t,d,Icon})=><article key={n}><span>{n} / PRINCIPLE</span><div><Icon size={26} strokeWidth={1.6}/></div><h3>{t}</h3><p>{d}</p></article>)}</section><section className="why-banner"><span className="eyebrow">LEARN → APPLY → BUILD → LAUNCH</span><h2>Knowledge is a start.<br/><em>Practice makes it yours.</em></h2><A className="btn btn-secondary" to="/courses">Explore the courses <ArrowUpRight size={16}/></A></section><FinalPrompt/></PageFrame>}
function BlogsPage(){return <PageFrame><PageHero label="BLOGS / SAMPLE ARTICLES" title={<>Practical notes on<br/><em>AI and SAP.</em></>} copy="Short guides for learning, building, and using AI thoughtfully."/><section className="blog-index section-pad"><div className="blog-index-head"><h2>Read, explore,<br/><em>put it to work.</em></h2><p>Three sample blog posts based on SARKTEK’s course and bootcamp topics.</p></div><div className="blog-grid">{blogPosts.map(post=><BlogCard key={post.slug} post={post}/>)}</div><A className="btn btn-secondary" to="/courses">Explore courses <ArrowUpRight size={16}/></A></section></PageFrame>}
function BlogDetail({post}:{post:BlogPost}){return <PageFrame><div className="crumb detail-crumb"><A to="/">Home</A><ChevronRight size={13}/><A to="/#journal">Blogs</A><ChevronRight size={13}/><span>{post.title}</span></div><article className="blog-article"><header className="blog-article-head"><span className="blog-meta">SAMPLE BLOG <i/> {post.category} <i/> {post.readTime}</span><h1>{post.title}</h1><p>{post.excerpt}</p></header><img className="blog-article-image" src={post.image} alt={post.alt}/><div className="blog-article-body">{post.sections.map((section,i)=><section key={section.heading}><span>0{i+1}</span><div><h2>{section.heading}</h2><p>{section.body}</p></div></section>)}</div><div className="blog-article-actions"><A className="btn btn-secondary" to="/#journal"><ArrowLeft size={16}/> All articles</A><A className="btn btn-primary" to="/courses">Explore courses <ArrowUpRight size={16}/></A></div></article></PageFrame>}
function ContactPage(){const[status,setStatus]=useState('');const query=new URLSearchParams(window.location.search);const selectedCourse=query.get('course');const selectedBootcamp=query.get('bootcamp');const initialCourse=courses.find(course=>course.slug===selectedCourse)?.title||bootcamps.find(item=>item.slug===selectedBootcamp)?.title||'';return <PageFrame><section className="contact-layout section-pad"><div className="contact-aside"><Eyebrow>CONTACT SARKTEK</Eyebrow><h1>Let’s talk about<br/><em>what fits.</em></h1><div className="contact-details"><a href="tel:+917396681595"><Phone size={18}/><span>73966 81595</span></a><a href="tel:+917702388845"><Phone size={18}/><span>77023 88845</span></a><a href="mailto:info@sarktek.in"><Mail size={18}/><span>info@sarktek.in</span></a><a href="https://www.sarktech.in" target="_blank" rel="noreferrer"><Globe2 size={18}/><span>www.sarktech.in</span></a><div><MapPin size={18}/><span>Madhapur, Hyderabad</span></div></div><A className="btn btn-secondary contact-courses" to="/courses">Browse courses <ArrowRight size={16}/></A></div><form className="contact-form" onSubmit={e=>{e.preventDefault();setStatus('Required fields are complete. This preview did not send or store your information.')}}><div className="form-row"><label><span className="field-label-row"><span>Your name</span><b aria-hidden="true">*</b></span><input name="name" autoComplete="name" required placeholder="Name"/></label><label><span className="field-label-row"><span>Email address</span><b aria-hidden="true">*</b></span><input type="email" name="email" autoComplete="email" required placeholder="you@example.com"/></label></div><div className="form-row"><label><span className="field-label-row"><span>Interested in</span><b aria-hidden="true">*</b></span><select required defaultValue={initialCourse}><option value="" disabled>Select a course or bootcamp</option>{courses.map(c=><option key={c.slug}>{c.title}</option>)}{bootcamps.map(b=><option key={b.slug}>{b.title}</option>)}</select></label><label><span className="field-label-row"><span>Your background</span><small>OPTIONAL</small></span><select defaultValue=""><option value="">Select one</option>{['Student','Working professional','Educator','Entrepreneur','NGO / social work','Other'].map(o=><option key={o}>{o}</option>)}</select></label></div><label><span className="field-label-row"><span>What would you like to know?</span><small>OPTIONAL</small></span><textarea rows={4} placeholder="Your question"/></label><button className="btn btn-primary" type="submit">Check required fields <Check size={16}/></button>{status&&<p className="form-status" role="status">{status}</p>}</form></section></PageFrame>}
function FinderPage(){const[step,setStep]=useState(0);const[answers,setAnswers]=useState(['','','']);const q1=['Non-technical student','CS or IT student','Management student','SAP, BI or data professional','Teacher','Entrepreneur','Priest or religious leader','NGO or social worker','Youth or student','Small or mid-size business owner','Change maker'];const q2=['Use AI confidently','Build AI agents','Apply AI to business','SAP analytics','SAP data cloud','SAP integration','Practical AI for my role'];const q3=['No coding','Basic programming','Comfortable with Python','Not sure'];const opts=[q1,q2,q3];const update=(value:string)=>setAnswers(current=>current.map((answer,index)=>index===step?value:answer));let rec:Course|Bootcamp|undefined;if(answers[0].includes('Priest'))rec=bootcamps[0];else if(answers[0].includes('Teacher'))rec=bootcamps[1];else if(answers[0].includes('Entrepreneur'))rec=bootcamps[3];else if(answers[0].includes('NGO'))rec=bootcamps[3];else if(answers[0].includes('Youth'))rec=bootcamps[4];else if(answers[0].includes('business owner')||answers[0].includes('Business owner'))rec=bootcamps[2];else if(answers[0].includes('Change maker'))rec=bootcamps[3];else if(answers[1]==='Build AI agents'||answers[0].includes('CS'))rec=courses[1];else if(answers[1]==='SAP analytics')rec=courses[3];else if(answers[1]==='SAP data cloud')rec=courses[4];else if(answers[1]==='SAP integration')rec=courses[5];else if(answers[1]==='Apply AI to business'||answers[0].includes('Management'))rec=courses[2];else rec=courses[0];const href=rec&&'category'in rec?`/courses/${rec.slug}`:`/bootcamps/${rec.slug}`;const recDescription=rec?('summary'in rec?rec.summary:rec.headline):'';const codingFit=rec&&'category'in rec?(rec.slug==='agentic-ai-computer-science'?(answers[2]==='No coding'?'You selected no coding, but this course requires basic programming. A Python refresher is included.':'Basic programming is required; a Python refresher is included.'):rec.slug==='ai-for-management'||rec.slug==='ai-for-non-ai-people'?'No coding is required for this course.':`You selected ${answers[2].toLowerCase()}; coding prerequisites are not specified for this course.`):`You selected ${answers[2].toLowerCase()}; coding prerequisites are not specified for this bootcamp.`;const finderReason=`Suggested for ${answers[0].toLowerCase()} interested in ${answers[1].toLowerCase()}. ${codingFit}`;return <PageFrame><section className="finder-page"><div className="crumb"><A to="/">Home</A><ChevronRight size={13}/><span>Find your course</span></div><div className="finder-layout"><aside className="finder-intro"><Eyebrow>A QUICK COURSE FINDER</Eyebrow><h1>Find a path<br/><em>that fits.</em></h1><p>Answer three short questions to narrow down a course or bootcamp. Change your answers or browse everything at any time.</p><div className="finder-benefits"><div><span>01</span><b>Start with your background</b></div><div><span>02</span><b>Choose what you want to learn</b></div><div><span>03</span><b>Check the programme requirements</b></div></div><div className="finder-resource-links"><A to="/courses">Browse six courses <ArrowUpRight size={15}/></A><A to="/bootcamps">Browse five bootcamps <ArrowUpRight size={15}/></A></div></aside><div className="finder-form-column"><div className="finder-box"><div className="finder-progress"><span>COURSE FINDER</span><span>{step<3?`QUESTION 0${step+1} / 03`:'YOUR SUGGESTION'}</span><div><i style={{width:`${step===3?100:(step+1)*33.33}%`}}/></div></div>{step<3?<><h2 aria-live="polite">{['What best describes you?','What would you like to work on?','How comfortable are you with coding?'][step]}</h2><div className="option-grid">{opts[step].map(option=><button key={option} className={answers[step]===option?'option selected':'option'} onClick={()=>update(option)} aria-pressed={answers[step]===option}>{option}{answers[step]===option&&<Check size={16}/>}</button>)}</div><div className="finder-controls"><button className="btn btn-secondary" onClick={()=>step>0&&setStep(step-1)} disabled={step===0}><ChevronLeft size={16}/> Back</button><button className="btn btn-primary" disabled={!answers[step]} onClick={()=>setStep(step+1)}>{step===2?'See my suggestion':'Continue'} <ArrowRight size={16}/></button></div></>:<div className="recommendation" aria-live="polite"><h2>A place to <em>start.</em></h2><article className="recommend-card"><span className="recommend-tag">{rec&&'category'in rec?rec.category+' COURSE':'10-HOUR IN-PERSON BOOTCAMP'}</span><h3>{rec?.title}</h3><p>{recDescription}</p><p className="recommend-reason">{finderReason}</p><A className="btn btn-primary" to={href}>See programme details <ArrowUpRight size={16}/></A></article><div className="finder-controls"><button className="btn btn-secondary" onClick={()=>setStep(2)}><ChevronLeft size={16}/> Change answers</button><A className="btn btn-secondary" to="/courses">View all courses <ArrowRight size={16}/></A></div></div>}</div><p className="finder-disclaimer">Suggestions are guidance based on your answers, not a guarantee of fit. <A to="/contact">Ask us a question</A>.</p></div></div></section></PageFrame>}
function PrivacyPage(){return <PageFrame><PageHero label="PRIVACY" title={<>Privacy for<br/><em>this preview.</em></>} copy="This explains how the demo behaves. It is not SARKTEK’s approved privacy notice."/><section className="policy section-pad"><h2>What this preview does</h2><p>The enquiry form validates fields in your browser. It does not send or save them. No analytics service, CRM, or email destination is connected in this project.</p><h2>Before accepting enquiries</h2><p>SARKTEK must approve a privacy notice and confirm the enquiry destination, data retention period, and any analytics or service providers before a live form is enabled.</p><h2>Contact</h2><p>For enquiries, email info@sarktek.in.</p><A className="btn btn-primary" to="/">Back to the homepage <ArrowUpRight size={15}/></A></section></PageFrame>}
function RedirectToBootcamps(){useEffect(()=>{window.location.replace('/bootcamps')},[]);return null}
function NotFound(){return <PageFrame><section className="not-found"><span className="eyebrow">404 / PAGE NOT FOUND</span><h1>This page took<br/><em>a different turn.</em></h1><p>Let’s get you back to the learning paths.</p><A className="btn btn-primary" to="/">Back to home <ArrowUpRight size={16}/></A></section></PageFrame>}
export default function App(){
 if(path==="/contact")return <ContactPage/>
 if(path==="/find-your-course")return <FinderPage/>
 if(path==="/courses")return <CoursesPage/>
 if(path.startsWith("/courses/")){const course=courses.find(item=>item.slug===path.slice("/courses/".length));return course?<CourseDetail course={course}/>:<NotFound/>}
 if(path==="/ai-bootcamps")return <RedirectToBootcamps/>
 if(path==="/bootcamps")return <BootcampsPage/>
 if(path.startsWith("/bootcamps/")){const item=bootcamps.find(entry=>entry.slug===path.slice("/bootcamps/".length));return item?<BootcampDetail item={item}/>:<NotFound/>}
 if(path==="/privacy")return <PrivacyPage/>
 return <Home/>
}
